   "summary": "個資題的情境通常是：公司蒐集、利用或外洩客戶、應徵者資料，問「怎麼做才合規」。判斷順序是：先看蒐集時有沒有告知法定事項（目的、類別、使用期間地區對象方式、當事人權利、不提供的影響），再看新用途有沒有超出原本同意範圍；超出就要重新取得同意或去識別化到無法回溯個人。外洩時要依個資法通知當事人，並依主管機關規定通報，同時也可能構成資通安全事件。跨國營運再加上 GDPR，隱私管理系統則是 ISO/IEC 27701（2019 版是 27001 的延伸；2025 年 10 月新版已改為可單獨驗證的獨立標準，舊題仍依 2019 版作答）。",
