   "summary": "縱深防禦的核心是「不要把安全押在單一產品或單一邊界上」，而是在實體、網路、主機、應用、資料、人員與流程各層都設防，一層被突破還有下一層擋住或偵測。考題常給一個攻擊事件（供應鏈入侵、勒索軟體從開發筆電擴散），問應補哪些層：微切分限制橫向移動、移除本機管理員權限、EDR 監控、特權存取管理、適應性 MFA 都屬於這類。要小心的是，只做備援、只做演練或只靠外包廠商的措施，不等於多層防護；放行所有外送流量更是反向操作。",
