   "summary": "CIA 三要素是資安的判斷基準：機密性（只讓該看的人看）、完整性（內容不被未授權竄改）、可用性（需要時能用）。考題給一個措施或事件，要你判斷它主要對應哪一項：加密、多因子驗證、存取限制、網路隔離偏機密性；備援、負載平衡、備份、容量規劃偏可用性；變更資料內容、竄改偏完整性。解題時看措施「主要目的」，而不是它還能附帶達到什麼效果，例如備份主要是可用性與復原，不是機密性。",
