     "context": "A 企業為一總部在台灣的股票上市公司，為國際知名的電子商務平台，主要業務包括企業對企業（B2B）及企業對個人（B2C）及消費者對消費者（C2C）的電子商務活動，員工超過 50,000 人，擁有 1,000 個據點及超過 2,000 部的伺服器及 300 座的機房，服務對象包括美國、英國、歐盟、俄羅斯、中國大陸、日本、韓國、台灣等等。在安全佈署上，除了每部服務主機建置防火牆外，亦佈署入侵防禦系統（Intrusion Prevention System，IPS），所有的存取控制以及安全性 Log 都收容到位於台灣的資訊安全監控中心（Security Operation Center，SOC）內的安全性資訊與事件管理系統（SIEM）中進行關聯資料分析，並且建立了完善的事件管理與追蹤系統。日前 A 企業位於英國的電子商務平台發生駭客入侵事故導致英國地區客戶超過 1,000 萬筆個人資料外洩，公司決定全公司各據點導入資訊安全管理系統（ISMS）及個人資料保護系統（PIMS）並於半年內完成。",
