     "answer": 2,
     "context": "【題組 2】迪菲-赫爾曼密鑰交換（Diffie-Hellman Key Exchange, D-H）是一種金鑰交換方法，其能夠讓通訊雙方在公開通道上建立金鑰，並且使用該金鑰在後續的通訊中作為共同金鑰來加密訊息內容。若小美和小明想要使用這個演算法來建立一個共同金鑰以利後續的訊息交換，則他們所使用的計算過程及參數如下所示：\n(g^a mod p)^b mod p = (g^b mod p)^a mod p\n．g：根數（base）\n．p：任意質數\n．a、b：分別為通訊兩端所各自選定的私鑰（秘密正整數值）\n．mod：取餘數（modulus）\n根據此式，小美和小明可以先各自選定私鑰 a 和 b，並搭配公開資訊 g 與 p 來計算得到共同金鑰 K。假設小美為金鑰交換的發起端，則金鑰建立流程如下所示：\n步驟 1.（小美）選定 a，計算 A = g^a mod p\n步驟 2.（公開通道）傳送 A, g, p 給小明\n步驟 3.（小明）選定 b，計算 B = g^b mod p，計算 K = A^b mod p\n步驟 4.（公開通道）傳送 B, g, p 給小美\n步驟 5.（小美）計算 K = B^a mod p\n在步驟 5. 以後，雙方皆得到一個相同的金鑰 K 可作為後續訊息交換使用。",
     "hint": "照題組附的步驟逐步算。先算出任一方送出的公開值，再用對方的公開值與自己的私鑰做同樣的次方取餘；也可以用另一方再算一次驗證。",
