   "summary": "當企業同時有 EDR（端點）、NDR（網路）、身分記錄時，單看任何一個來源只能看到攻擊的一小段；XDR 把這些來源集中起來做關聯分析，才能判斷「半夜登入、跑怪指令、連多個內部系統」是不是同一場攻擊。夜間與假日內部 SOC 沒人值班時，合理的安排是自動化工具先行阻斷、XDR 提供整合的可視性、由 MDR 服務商 24×7 即時分析與初步回應，再於隔日交接內部 SOC；而「把所有事件留到上班時間統一處理」或「夜間事件風險較低不用即時處理」都不合理。同時，SOC 的本質是「人員、程序、科技」三要素，科技在輔助人員依程序完成任務，它做的是監控、管理與分析資訊安全設備與事件，並不包含應用程式碼解析、壓力測試這類開發測試工作。",
