     "context": "XYZ 公司為一晶片設計公司，經最高管理階層會議決議，擬在 3~5 年間達成上市的目標，並於今年開始提交永續報告書，其中資訊安全管理策略議題章節草擬規劃如下【圖 1】，資訊安全架構如下【圖 2】。\n【圖 1】策略議題：資訊安全管理\n2023 年進度、成果：\n．導入 ISO 27001 資訊安全管理系統標準\n．資安管理範疇納入供應商範圍，邀集供應商舉辦資安訓練，提升供應鏈廠商資安防護能力。\n．頒布「產品安全管理政策」，各產品線產品必須從需求、設計、編碼、測試、交付、維護等不同產品開發階段，落實執行「產品安全開發生命週期（Product Security Development Life Cycle, PSDLC）」程序。\n．實施各產品線每季執行 PSDLC 稽核，並發出報告做為實行成效與改進的依據，達到產品安全品質目標。\n．建立外部威脅情資蒐集程序，定期發布與公司產品安全相關情資訊息給各 BU 事業群參考，並分析潛在風險與可能影響，發揮早期預警功用。\n．建置全公司模糊測試平臺與品質標準，整合模糊測試工具與管理系統，確保各產品線能夠依循一致流程，達到安全品質要求。\n短期目標（1-3 年）：\n．預計取得 ISO 27001 認證\n．預計取得車載資安國際標準 TISAX 認證\n．修訂公司 IP 資安保護政策，確保遵循 IP 轉移規範與網路使用規範保障資訊安全。\n．拓展資安管理至供應鏈，強化企業資安合規性。\n．修訂派遣外包合約，提高派遣外包人員資訊安全意識及強化規範，以降低相關風險。\n．所有產品線完成導入開源第三方軟體註冊/審核/掃描/修補流程，降低開源第三方軟體安全漏洞風險。\n．集中管理全產品線安全通報事件，有效落實漏洞追蹤與修補。\n中長期目標（3-10 年）：\n．建置資訊安全監控中心（Security Operations Center, SOC），即時偵測資訊安全事件與告警的機制，並定期檢測資訊系統架構。\n．建立軟體自動化安全檢測技術，持續提升資安檢測能量。\n．建立軟體物料清單（SBOM）系統機制，清楚掌握軟體內容組成/版本/來源/漏洞等資訊，滿足高安全強度合規需求。\n．針對產品安全漏洞通報訊息進行分析，強化現行產品開發流程不足之處，持續提升產品安全品質。\n【圖 2】資訊安全管理架構：XYZ 科技為管理資訊安全風險之目的，成立資訊安全委員會，由共同營運長及公司執行副總經理暨財務長擔任召集人，定期檢討資通安全、產品安全以及資料安全的執行情況，每半年至少召開一次，並得視資安風險管理需要隨時召開會議，並每年定期向董事會報告資訊安全檢查情形。資訊安全委員會之下分資通安全、產品安全、資料安全三項：資通安全涵蓋資通安全管理、規劃、督導及推動執行；產品安全涵蓋產品安全框架規劃與導入，產業合規、程序制定、教育訓練、威脅模型、測試規範、漏洞管理等；資料安全涵蓋制定、執行及討論智慧財產權資訊管理規範。",
