   "summary": "風險由三個要素組成：威脅（可能造成損害的來源或事件）、弱點（系統、流程、人員上的缺陷）、資產與其衝擊。威脅要利用弱點才會對資產造成損害，此時才形成風險，再評估發生的可能性與影響程度。三者不能混淆，更不能把「有弱點」直接等同於「有高風險」，也不能因為買了高階設備就認定風險已消失，必須依實際實施與有效性評估剩餘風險。威脅來源要看能力與動機：關鍵基礎設施面臨國家背景的 APT 組織，能力最強且目的就是癱瘓或情蒐，威脅最大。攻擊類型方面，主動式攻擊是攻擊者主動對目標發動，例如 DDoS、緩衝區溢位、暴力破解。",
