   "guidePages": "",
   "inGuide": true,
   "summary": "風險處理有四種基本策略，判斷看「實際做了什麼」。風險避免（規避）是乾脆不做那件事，例如關閉風險過高的海外網站、不自行處理金流；風險降低（修改、緩解）是動手改變機率或衝擊，例如導入安全開發流程與稽核、強化備份；風險轉移／分擔是把損失的一部分交給別人，例如投保資安險、合約約定委外廠商負擔；風險接受（保留）是在風險可接受時決定承受。情境題要注意兩件事：一是「措施做完後仍剩下的風險」叫剩餘（殘餘）風險；二是事件已造成重大損失、超出可承受範圍時，選「接受」通常最不合適。",
