   "summary": "風險處理不是做完就結案。完成風險處理後要持續監督與再評估：確認措施真的有效、剩餘風險有沒有降到風險胃納之內，環境改變時也要重新評鑑。常見情境有四種：第一，風險回應後再評估發現沒降下來，原因可能是規劃不當、尚未執行完或沒落實；第二，營運重大改變（接到政府標案、遷雲、新法規）時，要臨時進行風險評鑑，這是「監督與複核」發現環境變化而觸發的；第三，遷到雲端後仍須持續監控組態與稽核報告，並能對未授權變更告警或自動修復，一次性掃描不夠；第四，時程題要倒推：風險回應最遲須在規定期間內確認有效，且要早於業務上線的時點。",
