     "context": "（題組 1）A 集團是全球知名飯店集團，目前在全球超過 120 個國家，擁有約 6 千家旅館，旅館遍及亞洲、美洲、歐洲等地，並於 2016 年收購位於美國紐約的 BB 酒店。\n在 2018 年，BB 酒店房務系統遭駭客入侵造成 3 億多筆個資資料外洩，已知外洩資料中，包含客戶的姓名、通訊地址、電話號碼、電子信箱、護照號碼、出生日期、性別等資料。\n經查發現，這並不是 BB 酒店第一次遭駭客入侵而外洩客戶資料，早在 2014 年，BB 酒店就曾發生過客戶個資外洩事件。",
